// Helper model: SETUP/LEGAL (inferred from CHK-005 context), apb_busy and OUTST
logic apb_setup_legal;
logic apb_busy;
logic outst;

assign apb_setup_legal = i_apb_psel && !i_apb_penable &&
                         (i_apb_paddr[1:0] == 2'b00) &&
                         (!i_apb_pwrite || (i_apb_pstrb == 4'b1111));

always_ff @(posedge i_clk_core) begin
  if (!i_rst_n_core) begin
    apb_busy <= 1'b0;
    outst    <= 1'b0;
  end else begin
    if (apb_setup_legal)
      apb_busy <= 1'b1;
    else if (i_apb_psel && i_apb_penable && o_apb_pready)
      apb_busy <= 1'b0;

    if (i_tlul_d_valid && outst)
      outst <= 1'b0;
    else if (o_tlul_a_valid && i_tlul_a_ready && !i_tlul_d_valid)
      outst <= 1'b1;
  end
end

// CHK-012: Channel A payload equals the captured APB request (BR-3-03, BR-3-04, BR-6.2-13, BR-9-03, BR-9-05, BR-1.3-01, BR-1.3-02, BR-6.3-10, BR-6.3-12)
a_CHK_012: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  apb_setup_legal |=>
    (o_tlul_a_opcode == ($past(i_apb_pwrite) ? 3'b000 : 3'b100)) &&
    (o_tlul_a_address[PARA_ADDR_W-1:2] == $past(i_apb_paddr[PARA_ADDR_W-1:2])) &&
    (o_tlul_a_address[1:0] == 2'b00) &&
    (!$past(i_apb_pwrite) || (o_tlul_a_data == $past(i_apb_pwdata))))
  else begin fails_CHK_012++; $display("NNC_FAIL CHK-012 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (apb_setup_legal)) hits_CHK_012 <= hits_CHK_012 + 1;

// CHK-013: A request is raised only after a legal Setup (BR-5.4-05, BR-15.3-07, BR-3-07, BR-5.4-02, BR-6.2-06, BR-1.1-01)
a_CHK_013: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (o_tlul_a_valid && !$past(o_tlul_a_valid) && $past(i_rst_n_core)) |-> $past(apb_setup_legal))
  else begin fails_CHK_013++; $display("NNC_FAIL CHK-013 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (o_tlul_a_valid && !$past(o_tlul_a_valid) && $past(i_rst_n_core))) hits_CHK_013 <= hits_CHK_013 + 1;

// CHK-014: Channel A held and stable until accepted (BR-3-08, BR-5.4-03, BR-6.2-07, BR-6.2-11, BR-6.2-13, BR-6.3-07, BR-10.1-04, BR-15.3-02, BR-6.2-06)
a_CHK_014: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (o_tlul_a_valid && !i_tlul_a_ready) |=>
    o_tlul_a_valid && $stable(o_tlul_a_opcode) && $stable(o_tlul_a_address) &&
    $stable(o_tlul_a_data) && $stable(o_tlul_a_param) && $stable(o_tlul_a_size) &&
    $stable(o_tlul_a_mask) && $stable(o_tlul_a_source) && $stable(o_tlul_a_user))
  else begin fails_CHK_014++; $display("NNC_FAIL CHK-014 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (o_tlul_a_valid && !i_tlul_a_ready)) hits_CHK_014 <= hits_CHK_014 + 1;

// CHK-015: o_tlul_a_valid drops after the handshake (BR-10.1-04, BR-6.3-06, BR-3-06, BR-1.1-01, TL-T3.2-03)
a_CHK_015: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (o_tlul_a_valid && i_tlul_a_ready) |=> !o_tlul_a_valid)
  else begin fails_CHK_015++; $display("NNC_FAIL CHK-015 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (o_tlul_a_valid && i_tlul_a_ready)) hits_CHK_015 <= hits_CHK_015 + 1;

// CHK-016: At most one TL-UL request outstanding, only inside an APB transfer (BR-3-06, BR-3-07, BR-5.4-01, BR-5.4-06, BR-6.3-06, BR-15.3-03, BR-1.1-04, TL-T3.2-03)
a_CHK_016: assert property (@(posedge i_clk_core) disable iff (!i_rst_n_core)
  (o_tlul_a_valid || outst) |->
    (!o_tlul_a_valid || (!outst && apb_busy)) && (!outst || apb_busy))
  else begin fails_CHK_016++; $display("NNC_FAIL CHK-016 @%0t", $time); end
always_ff @(posedge i_clk_core) if (!(!i_rst_n_core) && (o_tlul_a_valid || outst)) hits_CHK_016 <= hits_CHK_016 + 1;

// CHK-017: Constant channel A fields and legal opcode encoding (BR-2.3-04, BR-2.3-05, BR-3-20, BR-5.4-01, BR-6.2-07, BR-6.2-08, BR-6.2-09, BR-6.2-10, BR-6.2-11, BR-6.2-12, BR-6.2-14, BR-8-04, BR-8-05, BR-8-08, BR-9-05, BR-9-07, BR-9-08, BR-15.3-04, BR-15.3-05, BR-20-06, BR-20-09, BR-1.1-04, TL-T3.1-01, TL-T3.3-03, TL-T4.1.3.3-02, TL-T4.1.3.4-02, TL-T4.1.3.4-04, TL-T4.1.3.5-07)
a_CHK_017: assert property (@(posedge i_clk_core)
  1'b1 |->
    (o_tlul_a_param == 3'b000) && (o_tlul_a_size == 2'b10) &&
    (o_tlul_a_mask == 4'b1111) &&
    (o_tlul_a_source == PARA_SRC_W'(PARA_SRC_ID)) &&
    (o_tlul_a_user == '0) &&
    (o_tlul_a_opcode[1:0] == 2'b00) && (o_tlul_a_address[1:0] == 2'b00) &&
    (o_tlul_a_opcode == 3'b000 || o_tlul_a_opcode == 3'b100))
  else begin fails_CHK_017++; $display("NNC_FAIL CHK-017 @%0t", $time); end
always_ff @(posedge i_clk_core) if (1'b1) hits_CHK_017 <= hits_CHK_017 + 1;
